{
  "identity": {
    "name": "Northwest Roof Restoration, LLC",
    "location": "Meridian, Idaho (with an additional branch in Post Falls, Idaho)",
    "claims": [
      {
        "statement": "Northwest Roof Restoration is a family-owned roofing company based in Meridian, Idaho.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Northwest Roof Restoration is a family-owned roofing company in Meridian, serving Boise, Eagle, Nampa, Caldwell, Post Falls, and the Treasure Valley since 2000"
      },
      {
        "statement": "The company operates locations at 1028 E Cayman Dr in Meridian and 728 S Gold Finch Rd in Post Falls.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Northwest Roof Restoration serves Meridian, Boise, Eagle, Nampa, Caldwell, Kuna, Star, Middleton, and Post Falls from 1028 E Cayman Dr, Meridian, ID 83642"
      },
      {
        "statement": "The business maintains dual operating addresses in Idaho.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/contact-us",
        "quote": "1028 E Cayman Dr, Meridian, ID 83642 728 S Gold Finch Rd, Post Falls, ID 83854"
      }
    ]
  },
  "industry": {
    "industry": "Roofing contracting (residential and commercial)",
    "activities": [
      "Roof repair and leak detection",
      "New roof installation",
      "Commercial roofing (TPO, PVC, EPDM, and metal)",
      "Roof inspections and certifications",
      "Emergency storm damage tarping and insurance restoration work",
      "Re-roofing"
    ],
    "claims": [
      {
        "statement": "The business provides roof repair, new installations, and commercial roofing.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Roof repair, new roof installation, and commercial roofing from Northwest Roof Restoration, LLC."
      },
      {
        "statement": "Commercial roofing capabilities include repairs, TPO and PVC single-ply membranes, metal roofing, and inspections.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/commercial-roofer",
        "quote": "We handle commercial roof repair, flat roof systems, TPO and PVC membranes, metal roofing, inspections, and full commercial roof replacement"
      },
      {
        "statement": "The business is a roofing contractor rather than an HVAC, plumbing, or electrical contractor.",
        "label": "inference",
        "sourceUrl": "https://nwroof.net/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://nwroof.net/",
    "claims": [
      {
        "statement": "The company has operated under the same ownership since 2003.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "under the same ownership since 2003."
      },
      {
        "statement": "The company's regular business hours are Monday through Friday from 8 AM to 5 PM.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/contact-us",
        "quote": "Monday - Friday: 8 AM - 5 PM"
      },
      {
        "statement": "The website was designed by Trafficology.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "2022 Design by Trafficology"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The business certifies and inspects roofs for compliance with state regulations.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Our company is equipped to certify and inspect all roofs to ensure that they are in compliance with all state regulations."
      },
      {
        "statement": "The company holds a contractor registration with the State of Idaho Division of Occupational and Professional Licenses.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    ],
    "limitations": "The website notes that the company conducts inspections to ensure roofs meet state regulations, but it does not publish an Idaho contractor registration or license number on its public pages."
  },
  "existingSoftware": [
    {
      "product": "Google Tag Manager",
      "purpose": "Website analytics and tracking tag deployment",
      "evidence": {
        "statement": "The website loads script assets from googletagmanager.com.",
        "label": "inference",
        "sourceUrl": "https://nwroof.net/",
        "quote": null
      }
    },
    {
      "product": "Tawk.to",
      "purpose": "Website chat widget",
      "evidence": {
        "statement": "The website references the host embed.tawk.to and includes an Online chat status indicator.",
        "label": "inference",
        "sourceUrl": "https://nwroof.net/",
        "quote": null
      }
    },
    {
      "product": "Weblium",
      "purpose": "Content management system and web form handling",
      "evidence": {
        "statement": "The site loads assets and endpoints from api.weblium.com and us-central1-weblium-contact-form-app.cloudfunctions.net.",
        "label": "inference",
        "sourceUrl": "https://nwroof.net/",
        "quote": null
      }
    },
    {
      "product": "Standard Web Forms / Email Intake",
      "purpose": "Customer inquiry and estimate request collection",
      "evidence": {
        "statement": "Prospective clients request estimates via site forms or direct email.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "email [redacted], or use the Request a Free Estimate form on this site, and our team will get back to you soon."
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Inbound estimate requests collected through website forms depend on manual asynchronous callbacks rather than real-time calendar booking.",
      "label": "fact",
      "sourceUrl": "https://nwroof.net/",
      "quote": "Leave us your info, and our roofing contractors will get back to you asap!"
    },
    {
      "statement": "Online inquiries are directed to email or web forms without integrated field-service management customer portal links.",
      "label": "fact",
      "sourceUrl": "https://nwroof.net/",
      "quote": "email [redacted], or use the Request a Free Estimate form on this site, and our team will get back to you soon."
    }
  ],
  "problems": [
    {
      "problem": "Potential lead response delays resulting from manual triage of website form submissions and emails.",
      "label": "hypothesis",
      "basis": "The website indicates staff will 'get back to you asap' and 'get back to you soon' after receiving contact form inputs, which relies on human review rather than instant automated CRM scheduling."
    },
    {
      "problem": "Company operates outside ForgeX's primary target service segment.",
      "label": "fact",
      "basis": "The business operates strictly in roofing installation, restoration, and repairs, rather than HVAC, plumbing, or electrical trades."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Roofing-specific field service and CRM software (e.g., JobNimbus, AccuLynx, or Roofr)",
      "addresses": "Lead pipeline management, aerial measurement integration, automated follow-up sequences, and customer proposal tracking.",
      "alreadyOwned": false
    },
    {
      "solution": "Weblium native form notifications and webhook integrations",
      "addresses": "Instantly sending form submissions via SMS or email to office staff or dispatchers.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "Because Northwest Roof Restoration is a roofing contractor outside ForgeX's core HVAC, plumbing, and electrical focus, no ForgeX implementation is recommended."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solutions are recommended for delivery."
  },
  "humanReview": [
    "Manual physical or drone roof damage inspection before issuing binding replacement or repair estimates.",
    "Human review of insurance scope sheets and carrier documentation for hail, storm, and wind claims."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Attempting automated roof quote generation without visual inspection of decking, slope, and flashing risks significant underbidding or material mismatch."
    },
    {
      "type": "compliance",
      "description": "Roof certifications and commercial membrane installations require compliance with Idaho state and local building codes and manufacturer warranty specifications."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website provides free estimates and does not publish specific project, per-square, or hourly pricing; therefore, commercial value cannot be calculated from website figures."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "General Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://nwroof.net/"
      },
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://nwroof.net/"
      },
      {
        "kind": "web form",
        "value": "https://nwroof.net/",
        "sourceUrl": "https://nwroof.net/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "What CRM or field management platform do you use to manage roof estimate requests across the Treasure Valley and Post Falls?",
      "How quickly is your office team able to respond to online estimate requests during storm events?",
      "Do you rely primarily on word-of-mouth and builder referrals, or do you actively buy digital roofing leads?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://nwroof.net/",
        "usedFor": "Business identity, phone, email, services offered, locations, and lead capture forms."
      },
      {
        "url": "https://nwroof.net/contact-us",
        "usedFor": "Operating hours, dual office addresses, and contact methods."
      },
      {
        "url": "https://nwroof.net/commercial-roofer",
        "usedFor": "Commercial roofing materials, commercial services, and project references."
      },
      {
        "url": "https://nwroof.net/service-area",
        "usedFor": "Geographic service area coverage in Treasure Valley and North Idaho."
      },
      {
        "url": "https://nwroof.net/service-area/roofers-meridian-idaho-commercial-residential",
        "usedFor": "Meridian service area details and commercial project history."
      },
      {
        "url": "https://nwroof.net/service-area/roofers-post-falls-idaho-commercial-residential",
        "usedFor": "Post Falls office address and North Idaho service details."
      },
      {
        "url": "https://nwroof.net/testimonials",
        "usedFor": "Review evaluation and verifying management representations."
      },
      {
        "url": "https://nwroof.net/new-roof-installation",
        "usedFor": "Residential installation processes and materials."
      },
      {
        "url": "https://nwroof.net/roof-repairs",
        "usedFor": "Repair scope, emergency services, and insurance assistance."
      },
      {
        "url": "https://nwroof.net/privacy-policy",
        "usedFor": "Privacy policies, cookie usage, and data handling."
      },
      {
        "url": "https://nwroof.net/blog",
        "usedFor": "Industry news and blog content assessment."
      },
      {
        "url": "https://nwroof.net/gallery",
        "usedFor": "Project portfolio review."
      }
    ],
    "limitations": [
      "Employee headcount is not stated on the public website.",
      "Specific state contractor registration numbers are not published on the website.",
      "Service and installation pricing is not disclosed on the site, preventing commercial value calculations.",
      "Owners and executive leadership are not presented on dedicated team or about pages (names appear only within customer testimonials, which cannot be used per evidence rules)."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Northwest Roof Restoration, LLC is a residential and commercial roofing contractor. ForgeX's target market is owner-led home-service contractors in HVAC, plumbing, and electrical with approximately 10 to 75 staff who pay for leads. Roofing falls outside ForgeX's target vertical, and the website does not provide evidence of 10 to 75 staff or paid lead generation."
  }
}
